<script setup>
import { computed, reactive } from 'vue'
import { Head, useForm } from '@inertiajs/vue3'
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'

const props=defineProps({incomingOrders:Array,staff:Array,workOrders:Array})
const intake=reactive({})
const drying=reactive({})
props.incomingOrders.forEach(order=>{intake[order.id]={extraction_method:'squeezer',assigned_to:''}})
props.workOrders.filter(order=>order.status==='awaiting_drying_assignment').forEach(order=>{drying[order.id]={drying_method:'heatsetting',assigned_to:''}})
const extractStaff=(method)=>props.staff.filter(s=>s.manufacturing_role===(method==='squeezer'?'finishing_squeezer':'finishing_hydro'))
const dryStaff=(method)=>props.staff.filter(s=>s.manufacturing_role===(method==='heatsetting'?'finishing_ironing':'finishing_tubetex'))
function start(order){useForm({...intake[order.id]}).post(route('man.finishing-workflow.start'),{preserveScroll:true})}
function assignDrying(order){useForm({...drying[order.id]}).post(route('man.finishing-workflow.drying',order.id),{preserveScroll:true})}
function send(workOrder){useForm({}).post(route('man.finishing-workflow.logistics',workOrder.id),{preserveScroll:true})}
</script>

<template>
    <Head title="Finishing Workflow"/><AuthenticatedLayout><main class="mx-auto max-w-7xl space-y-6 p-4 sm:p-6">
        <header class="rounded-3xl bg-gradient-to-r from-emerald-800 to-teal-600 p-6 text-white"><p class="text-xs font-black uppercase tracking-widest text-emerald-100">Finishing Supervisor</p><h1 class="mt-1 text-3xl font-black">Finishing Workflow</h1><p class="mt-2 text-sm text-emerald-100">Choose one Water Extraction route, review the returned JO, then assign one Drying route. Track inspection, packing, and Logistics handoff here.</p></header>
        <section class="rounded-2xl border bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900"><h2 class="text-xl font-black">JO received from Dyeing</h2><p v-if="!incomingOrders.length" class="mt-3 text-sm text-slate-500">No complete JO is waiting for Finishing.</p><article v-for="order in incomingOrders" :key="order.id" class="mt-4 rounded-xl border p-4 dark:border-zinc-700"><div class="flex flex-wrap justify-between gap-2"><div><h3 class="font-black">{{ order.jo_number }}</h3><p class="text-sm text-slate-500">{{ order.fabrics.length }} rolls · {{ order.fabrics.reduce((n,f)=>n+Number(f.weight),0).toFixed(2) }} / {{ order.required_weight }} kg</p></div></div><div class="mt-3 grid gap-3 md:grid-cols-3"><label class="text-sm font-semibold">Water Extraction<select v-model="intake[order.id].extraction_method" class="mt-1 w-full rounded-lg border p-2"><option value="squeezer">Squeezer — chemicals for texture</option><option value="hydro">Hydro — water extraction without chemicals</option></select></label><label class="text-sm font-semibold">Assigned staff<select v-model="intake[order.id].assigned_to" class="mt-1 w-full rounded-lg border p-2"><option value="">Select one staff member</option><option v-for="person in extractStaff(intake[order.id].extraction_method)" :key="person.id" :value="person.id">{{ person.name }}</option></select></label><button @click="start(order)" :disabled="!intake[order.id]?.assigned_to" class="self-end rounded-lg bg-emerald-700 px-4 py-2 font-bold text-white disabled:opacity-40">Assign Water Extraction</button></div><div class="mt-3 flex flex-wrap gap-2"><span v-for="f in order.fabrics" :key="f.id" class="rounded bg-slate-100 px-2 py-1 text-xs dark:bg-zinc-800">{{ f.code }} · {{ f.yarn_type }} · {{ f.weight }} kg</span></div></article></section>
        <section class="rounded-2xl border bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900"><h2 class="text-xl font-black">Active Finishing JOs</h2><p v-if="!workOrders.length" class="mt-3 text-sm text-slate-500">No JOs are currently in the Finishing workflow.</p><article v-for="order in workOrders" :key="order.id" class="mt-4 rounded-xl border p-4 dark:border-zinc-700"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-black">{{ order.sales_order?.jo_number }} <span class="font-normal text-slate-500">· {{ order.status.replaceAll('_',' ') }}</span></h3><p class="text-xs text-slate-500">Water extraction: {{ order.extraction_method }} · {{ order.extraction_operator?.name }}<span v-if="order.drying_method"> · Drying: {{ order.drying_method }} · {{ order.drying_operator?.name }}</span></p></div><button v-if="order.status==='ready_logistics'" @click="send(order)" class="rounded-lg bg-indigo-700 px-4 py-2 text-sm font-bold text-white">Pass all packed groups to Logistics</button></div>
            <div v-if="order.status==='awaiting_drying_assignment'" class="mt-3 grid gap-3 md:grid-cols-3"><label class="text-sm font-semibold">Drying route<select v-model="drying[order.id].drying_method" class="mt-1 w-full rounded-lg border p-2"><option value="heatsetting">Heatsetting — high temperature</option><option value="tubetex">Tubetext — low temperature</option></select></label><label class="text-sm font-semibold">Assigned staff<select v-model="drying[order.id].assigned_to" class="mt-1 w-full rounded-lg border p-2"><option value="">Select one staff member</option><option v-for="person in dryStaff(drying[order.id].drying_method)" :key="person.id" :value="person.id">{{ person.name }}</option></select></label><button @click="assignDrying(order)" :disabled="!drying[order.id]?.assigned_to" class="self-end rounded-lg bg-emerald-700 px-4 py-2 font-bold text-white disabled:opacity-40">Assign Drying</button></div>
            <div class="mt-3 flex flex-wrap gap-2"><span v-for="item in order.items" :key="item.id" class="rounded bg-slate-100 px-2 py-1 text-xs dark:bg-zinc-800">{{ item.fabric?.code }} · {{ item.status }}</span></div>
            <div v-if="order.package_groups?.length" class="mt-3 space-y-2"><p class="text-sm font-bold">Packed fabric groups</p><div v-for="group in order.package_groups" :key="group.id" class="rounded-lg bg-slate-50 p-3 text-xs dark:bg-zinc-800"><span class="font-black">{{ group.code }}</span> · {{ group.group_name || 'Fabric group' }} · {{ group.status }} · {{ group.items?.map(x=>x.work_item?.fabric?.code).join(', ') }}</div></div>
        </article></section>
    </main></AuthenticatedLayout>
</template>
